193	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
194	        Collection<Owner> owners;
195	        if (lastName != null) {
196	            owners = this.clinicService.findOwnerByLastName(lastName);
197	        } else {
198	            owners = this.clinicService.findAllOwners();
199	        }
200	        if (owners.isEmpty()) {
201	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	        }
203	        owners.forEach(this::populateHouseholdSize);
204	        List<OwnerDto> ownerDtos = new ArrayList<>();
205	        for (Owner owner : owners) {
206	            OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
207	            applyHouseholdMembershipCap(owner, ownerDto);
208	            ownerDtos.add(ownerDto);
209	        }
210	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
211	    }
