506	    /**
507	     * Cap the owner's membership level so it never exceeds one above the current maximum membership
508	     * level among the owner's household members (the other non-deleted owners sharing this owner's
509	     * {@code householdId}). When the household has no other member, no cap applies and the level is
510	     * left untouched. Any reduction is written back onto the given dto.
511	     *
512	     * @param owner    the owner whose household members bound the level (excluded from its own household)
513	     * @param ownerDto the mapped dto whose {@code membershipLevel} is capped in place
514	     */
515	    private void applyHouseholdMembershipCap(Owner owner, OwnerDto ownerDto) {
516	        String householdId = owner.getHouseholdId();
517	        if (!StringUtils.hasText(householdId) || ownerDto.getMembershipLevel() == null) {
518	            return;
519	        }
520	        Integer maxMemberLevel = this.clinicService.findAllOwners().stream()
521	            .filter(existing -> !existing.isDeleted())
522	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
523	            .filter(existing -> !java.util.Objects.equals(existing.getId(), owner.getId()))
524	            .map(this::membershipLevelOf)
525	            .max(Integer::compareTo)
526	            .orElse(null);
527	        if (maxMemberLevel != null && ownerDto.getMembershipLevel() > maxMemberLevel + 1) {
528	            ownerDto.setMembershipLevel(maxMemberLevel + 1);
529	        }
530	    }
