830	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
831	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
832	     *
833	     * @param value the raw value, may be {@code null}
834	     * @return the normalized value
835	     */
836	    private String normalizeForComparison(String value) {
837	        if (value == null) {
838	            return "";
839	        }
840	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
