35	    @Mapping(target = "telephoneDisplay", expression = "java(deriveTelephoneDisplay(owner))")
36	    @Mapping(target = "salutation", expression = "java(deriveSalutation(owner))")
37	    @Mapping(target = "fiscalYear", expression = "java(deriveFiscalYear(owner))")
38	    @Mapping(target = "selfLink", expression = "java(deriveSelfLink(owner))")
