53	    /**
54	     * The known region codes a member id can begin with, longest first so a longer code is matched
55	     * before any shorter one that shares its prefix.
56	     */
57	    List<String> MEMBER_ID_REGIONS = List.of("UNKNOWN", "NSW", "VIC", "QLD");
58	
59	    /**
60	     * Derive the locality region for an owner from its unified member id. The member id is formatted
61	     * {@code <REGION><FY><HASH8><CHK>}, so the locality is its leading region segment (the same region
62	     * the identity itself was built from: postcode range first, then the city-to-region table,
63	     * otherwise "UNKNOWN"). When no member id is present, the locality is "UNKNOWN".
64	     */
65	    default String deriveLocality(Owner owner) {
66	        String memberId = owner.getMemberId();
67	        if (memberId != null) {
68	            for (String region : MEMBER_ID_REGIONS) {
69	                if (memberId.startsWith(region)) {
70	                    return region;
71	                }
72	            }
73	        }
74	        return "UNKNOWN";
75	    }
76	
77	    /**
78	     * Region -> IANA timezone name, the pinned region-to-timezone table:
79	     * NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane.
80	     */
81	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
82	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
83	
84	    /**
85	     * Derive the owner's IANA timezone from its locality/region via the fixed region-to-timezone
86	     * table (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). Returns
87	     * {@code null} when the region has no mapping (e.g. "UNKNOWN"), so the field is absent from
88	     * the response.
89	     */
90	    default String deriveTimezone(Owner owner) {
91	        return REGION_TIMEZONE.get(deriveLocality(owner));
92	    }
93	
94	    /**
95	     * Derive the owner's age band from its birth date, computed against the registration date. The age
96	     * is the number of whole years between the birth date and the effective registration date (falling
97	     * back to the current date when no registration date is present): {@code MINOR} when under 18,
98	     * {@code ADULT} for 18-64 and {@code SENIOR} for 65 and over. Returns {@code null} when no birth
99	     * date was supplied, so the field is absent from the response.
100	     */
101	    default OwnerDto.AgeBandEnum deriveAgeBand(Owner owner) {
102	        java.time.LocalDate birthDate = owner.getBirthDate();
103	        if (birthDate == null) {
104	            return null;
105	        }
106	        java.time.LocalDate reference = owner.getRegistrationDate() != null
107	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
108	        int age = java.time.Period.between(birthDate, reference).getYears();
109	        if (age < 18) {
110	            return OwnerDto.AgeBandEnum.MINOR;
111	        }
112	        if (age < 65) {
113	            return OwnerDto.AgeBandEnum.ADULT;
114	        }
115	        return OwnerDto.AgeBandEnum.SENIOR;
116	    }
117	
118	    /**
119	     * Compute the owner's membership points: starting at 0, add 2 when an email is present, add 1
120	     * when {@code namesakeCount} is 0, add 2 for a household of 3 or more members, and add 3 for a
121	     * tenure of one or more elapsed fiscal years.
122	     */
123	    default int membershipPoints(Owner owner) {
124	        int points = 0;
125	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
126	            points += 2;
127	        }
128	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
129	            points += 1;
130	        }
131	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
132	            points += 2;
133	        }
134	        if (tenureFiscalYears(owner) >= 1) {
135	            points += 3;
136	        }
137	        return points;
138	    }
139	
140	    /**
141	     * Map membership points onto the numeric membership level: 1 for 0-1 points, 2 for 2-3 points,
142	     * 3 for 4-5 points and 4 for 6 or more points.
143	     */
144	    default int membershipLevel(int points) {
145	        if (points <= 1) {
146	            return 1;
147	        }
148	        if (points <= 3) {
149	            return 2;
150	        }
151	        if (points <= 5) {
152	            return 3;
153	        }
154	        return 4;
155	    }
156	
157	    /**
158	     * Compute the owner's tenure as the number of elapsed fiscal years: the difference between the
159	     * fiscal year of today and the fiscal year of the owner's registration date. A newly created
160	     * owner registered in the current fiscal year therefore has a tenure of zero, and an owner with
161	     * no registration date is treated as having zero tenure. Used to gate the tenure membership
162	     * points, which require a tenure of one or more elapsed fiscal years.
163	     */
164	    default long tenureFiscalYears(Owner owner) {
165	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
166	        if (registrationDate == null) {
167	            return 0;
168	        }
169	        return (long) fiscalYear(java.time.LocalDate.now()) - fiscalYear(registrationDate);
170	    }
171	
172	    /**
173	     * The fiscal year that the given date falls in. The fiscal year starts on 1 July, so a date in
174	     * July to December belongs to the fiscal year ending in the following calendar year, and a date
175	     * in January to June belongs to the fiscal year ending in the same calendar year. The fiscal
176	     * year is identified by that ending calendar year (e.g. 1 July 2026 to 30 June 2027 is 2027).
177	     */
178	    default int fiscalYear(java.time.LocalDate date) {
179	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
180	    }
181	
182	    /**
183	     * Derive the owner's fiscal year label, formatted {@code FY<YY>}, where {@code YY} is the last
184	     * two digits of the fiscal year that the (business-day-adjusted) registration date falls in
185	     * (e.g. {@code FY27} for a registration in the fiscal year ending 30 June 2027). Falls back to
186	     * the current date when no registration date is present.
187	     */
188	    default String deriveFiscalYear(Owner owner) {
189	        java.time.LocalDate reference = owner.getRegistrationDate() != null
190	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
191	        return String.format("FY%02d", fiscalYear(reference) % 100);
192	    }
193	
194	    /**
195	     * Known country calling codes, ordered longest-prefix-first, used to split a stored E.164
196	     * telephone into its country code and national digits when building {@code telephoneDisplay}.
197	     * Mirrors the country codes the create endpoint recognises ({@code +61} and {@code +1}).
198	     */
199	    List<String> TELEPHONE_COUNTRY_CODES = List.of("61", "1");
200	
201	    /**
202	     * Format the owner's stored E.164 telephone for humans: the country code, a single space, then
203	     * the national digits grouped in threes (e.g. {@code +61412345678} becomes
204	     * {@code +61 412 345 678}). Returns the raw value unchanged when it is null, not in E.164 form,
205	     * or carries an unrecognised country code.
206	     */
207	    default String deriveTelephoneDisplay(Owner owner) {
208	        String telephone = owner.getTelephone();
209	        if (telephone == null || !telephone.startsWith("+")) {
210	            return telephone;
211	        }
212	        String digits = telephone.substring(1);
213	        String countryCode = null;
214	        for (String code : TELEPHONE_COUNTRY_CODES) {
215	            if (digits.startsWith(code) && digits.length() > code.length()) {
216	                countryCode = code;
217	                break;
218	            }
219	        }
220	        if (countryCode == null) {
221	            return telephone;
222	        }
223	        String national = digits.substring(countryCode.length());
224	        StringBuilder grouped = new StringBuilder();
225	        for (int i = 0; i < national.length(); i++) {
226	            if (i > 0 && i % 3 == 0) {
227	                grouped.append(' ');
228	            }
229	            grouped.append(national.charAt(i));
230	        }
231	        return "+" + countryCode + " " + grouped;
232	    }
233	
234	    /**
235	     * Compose the owner's salutation from its title and last name: the title and last name separated
236	     * by a single space (e.g. {@code DR who}) when a title is present, or just the last name when no
237	     * title (null or blank) was supplied.
238	     */
239	    default String deriveSalutation(Owner owner) {
240	        String lastName = owner.getLastName();
241	        String title = owner.getTitle();
242	        if (title == null || title.isEmpty()) {
243	            return lastName;
244	        }
245	        return title + " " + lastName;
246	    }
247	
248	    /**
249	     * Derive the owner's canonical self link, formatted {@code /api/owners/<id>}. Returns
250	     * {@code null} when the owner has no id yet, so the field is absent from the response.
251	     */
252	    default String deriveSelfLink(Owner owner) {
253	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
254	    }
255	
256	    /**
257	     * Known metropolitan regions: an owner whose locality is one of these is 'METRO', any other
258	     * locality (including "UNKNOWN") is 'REGIONAL'. Mirrors the pinned city-to-region table.
259	     */
260	    java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
261	
262	    /**
263	     * Derive the owner's marketing segment, formatted {@code <TIER>_<AREA>}: one of
264	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
265	     * {@code STANDARD_REGIONAL}. TIER is {@code PREMIUM} when the owner's membershipLevel is 3 or
266	     * more, otherwise {@code STANDARD}. AREA is {@code METRO} when the owner's locality is a known
267	     * region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
268	     */
269	    default OwnerDto.OwnerSegmentEnum deriveOwnerSegment(Owner owner) {
270	        String tier = membershipLevel(membershipPoints(owner)) >= 3 ? "PREMIUM" : "STANDARD";
271	        String area = METRO_REGIONS.contains(deriveLocality(owner)) ? "METRO" : "REGIONAL";
272	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
273	    }
274	
275	    /**
276	     * Known disposable-email domains. Mirrors the create endpoint's blocklist: an email whose domain
277	     * exactly matches one of these is rejected at creation, so a stored owner never carries one. They
278	     * anchor the weaker "disposable-adjacent" relation used by {@link #deriveRiskFlag(Owner)}.
279	     */
280	    java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
281	        "mailinator.com", "tempmail.com", "guerrillamail.com");
282	
283	    /**
284	     * Derive the owner's risk flag: {@code true} when the owner warrants a manual risk review because
285	     * any of these holds — the owner is a possible duplicate ({@code possibleDuplicate} is true), the
286	     * owner's email domain is disposable-adjacent (see {@link #isDisposableAdjacentEmail(String)}), or
287	     * the owner's city is over its soft capacity ({@code capacityWarning} is true) — otherwise
288	     * {@code false}.
289	     */
290	    default boolean deriveRiskFlag(Owner owner) {
291	        boolean possibleDuplicate = Boolean.TRUE.equals(owner.getPossibleDuplicate());
292	        boolean overSoftCapacity = Boolean.TRUE.equals(owner.getCapacityWarning());
293	        return possibleDuplicate || overSoftCapacity || isDisposableAdjacentEmail(owner.getEmail());
294	    }
295	
296	    /**
297	     * Whether an email's domain is "disposable-adjacent": not necessarily one of the exactly-blocked
298	     * disposable domains (those are rejected at creation and never stored), but close enough to warrant
299	     * review. A domain qualifies when it is, or is a subdomain of, a known disposable domain, or when it
300	     * shares the second-level label of one (e.g. {@code mailinator.org} or {@code mail.mailinator.com}
301	     * for the blocked {@code mailinator.com}). A {@code null}/blank email or one with no domain is not
302	     * disposable-adjacent.
303	     */
304	    private boolean isDisposableAdjacentEmail(String email) {
305	        if (email == null || email.isEmpty()) {
306	            return false;
307	        }
308	        int at = email.lastIndexOf('@');
309	        if (at < 0 || at == email.length() - 1) {
310	            return false;
311	        }
312	        String domain = email.substring(at + 1).toLowerCase(java.util.Locale.ROOT);
313	        String base = secondLevelLabel(domain);
314	        for (String disposable : DISPOSABLE_EMAIL_DOMAINS) {
315	            if (domain.equals(disposable) || domain.endsWith("." + disposable)) {
316	                return true;
317	            }
318	            if (base != null && base.equals(secondLevelLabel(disposable))) {
319	                return true;
320	            }
321	        }
322	        return false;
323	    }
324	
325	    /**
326	     * The second-level label of a dotted domain: the label immediately preceding the final (top-level)
327	     * label (e.g. {@code mailinator} for {@code mail.mailinator.com}). Returns {@code null} for a domain
328	     * with fewer than two labels.
329	     */
330	    private String secondLevelLabel(String domain) {
331	        String[] labels = domain.split("\\.");
332	        if (labels.length < 2) {
333	            return null;
334	        }
335	        return labels[labels.length - 2];
336	    }
337	
338	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
339	        OwnerPageDto ownerPageDto = new OwnerPageDto();
340	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
341	        ownerPageDto.setPage(ownerPage.getNumber());
342	        ownerPageDto.setSize(ownerPage.getSize());
343	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
344	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
345	        return ownerPageDto;
346	    }
347	}
